UPDATE perks SET short_description = 'Plant-based diet grants immunity to disease and better nourishment.', long_description = 'Living in harmony with nature, your diet is strictly herbivorous. This bond with the forest grants you immunity to disease and enhanced nourishment from plant-based foods. You can''t eat meat, if you do you Max Health is reduced by 25% until a you''ve had a full nights rest. You are also immune to diseases and all other food gives you double benefit.' WHERE name = 'Forest Child';
