UPDATE perks SET short_description = 'Issue faster pet orders.', long_description = 'Companions respond instantly to your Animal Handling commands.' WHERE name = 'Quick Command';
UPDATE perks SET short_description = 'Pick locks faster.', long_description = 'Disarm traps and locks swiftly and silently.' WHERE name = 'Quick Fingers';
UPDATE perks SET short_description = 'Reduce crafting time.', long_description = 'Complete crafting tasks significantly faster.' WHERE name = 'Quick Forge';
UPDATE perks SET short_description = 'Use healing faster.', long_description = 'Apply bandages or tonics more quickly.' WHERE name = 'Quick Patch';
UPDATE perks SET short_description = 'Restore ally morale.', long_description = 'Shout encouragement that replenishes stamina or morale.' WHERE name = 'Rally Cry';
UPDATE perks SET short_description = 'Quickly evaluate value.', long_description = 'Instantly estimate worth of items or traps.' WHERE name = 'Rapid Assessment';
UPDATE perks SET short_description = 'Bend space-time.', long_description = 'Tear through the veil to teleport or create explosive energy.' WHERE name = 'Reality Tear';
UPDATE perks SET short_description = 'Increase ally armor.', long_description = 'Grant temporary armor bonuses to nearby allies.' WHERE name = 'Reinforce Line';
UPDATE perks SET short_description = 'Sturdy bones give you an edge against injuries.', long_description = 'Your bones are exceptionally sturdy, providing a robust defense against injuries that would cripple others. When making a Fortitude test to resist injury, gain +5 for that test.' WHERE name = 'Resilient Frame';
UPDATE perks SET short_description = 'Chance to save materials.', long_description = 'Crafting sometimes doesn’t consume ingredients.' WHERE name = 'Resourceful';
UPDATE perks SET short_description = 'Stabilize critical allies.', long_description = 'Prevent an ally from dying at zero health.' WHERE name = 'Resuscitate';
UPDATE perks SET short_description = 'Encourage counterattacks.', long_description = 'Allies counterattack after taking damage.' WHERE name = 'Retaliate Order';
UPDATE perks SET short_description = 'Defeats restore mana.', long_description = 'Killing enemies renews a portion of your faith-based energy.' WHERE name = 'Righteous Zeal';
UPDATE perks SET short_description = 'Immobilize enemies with roots.', long_description = 'Entangle foes with vines that hold them in place.' WHERE name = 'Root Snare';
UPDATE perks SET short_description = 'Each rune grants unique powers of luck, magic, or craft.', long_description = 'From the moment of birth, every Dwarf bears a unique rune etched into their body, signifying their clan and heritage. These mystical runes are not just marks of identity; they bestow powerful benefits that shape the destiny of each Dwarf.\n\nExplorer''s Rune\nMarked by the Explorer''s Rune, your fate is intertwined with fortune and discovery. The rune guides your hand, ensuring you find the best rewards on your journeys. Every time you roll on a loot table, roll twice and choose the outcome.\n\nMagister''s Rune\nThe Magister''s Rune bestows upon you an innate mastery of mystical arts. This rune amplifies your connection to the magical realms, enhancing your spellcasting and mystical insights. You gain an extra Tag in either Arcana, Shamanism or Zeal.\n\nArtisan''s Rune\nBearing the Artisan''s Rune, your hands are gifted with extraordinary skill. This rune enhances your craftsmanship, making anything you create a testament to your exceptional talent. You gain Tag in Craft and a +2 for any skill test where you are using something you made your self.' WHERE name = 'Runic Destiny';
UPDATE perks SET short_description = 'Add extra enchantments.', long_description = 'Imbue crafted weapons or armor with an additional magical slot.' WHERE name = 'Runic Etching';
UPDATE perks SET short_description = 'Stationary casting boosts power.', long_description = 'Spells cast while standing still gain bonus potency.' WHERE name = 'Runic Focus';
UPDATE perks SET short_description = 'Preserve spell effects.', long_description = 'Extend the duration of magical scrolls you use.' WHERE name = 'Runic Memory';
UPDATE perks SET short_description = 'Faith empowers allies.', long_description = 'Channel devotion to bless allies and weaken unholy enemies.' WHERE name = 'Sacred Vow';
UPDATE perks SET short_description = 'Remember vital lore.', long_description = 'Occasionally recall hidden facts about the world.' WHERE name = 'Sage’s Recall';
UPDATE perks SET short_description = 'Recover more materials.', long_description = 'Dismantling equipment yields additional crafting resources.' WHERE name = 'Salvager';
UPDATE perks SET short_description = 'Recall ancient wisdom.', long_description = 'Unlock special dialogue or insights tied to history.' WHERE name = 'Scholar of the Old Ways';
UPDATE perks SET short_description = 'Withdrawn life grants quiet insight.', long_description = 'After character creation, gain a Perk in each of your Tag skills, but CHA tests suffer a permanent increase in difficulty by 2.' WHERE name = 'Secluded';
UPDATE perks SET short_description = 'Recover stamina after a kill.', long_description = 'Defeating an enemy restores a portion of your stamina or health.' WHERE name = 'Second Wind';
UPDATE perks SET short_description = 'Hide better in darkness.', long_description = 'Blend into shadows to become nearly invisible.' WHERE name = 'Shadowmeld';
UPDATE perks SET short_description = 'Defensive stance boosts resistance.', long_description = 'Form an impenetrable guard that reduces ranged damage taken.' WHERE name = 'Shield Wall';
UPDATE perks SET short_description = 'Move quietly.', long_description = 'Reduce sound generated by movement.' WHERE name = 'Silent Steps';
UPDATE perks SET short_description = 'Eliminate silently.', long_description = 'Perform stealth kills without alerting others.' WHERE name = 'Silent Takedown';
UPDATE perks SET short_description = 'Improve persuasion.', long_description = 'Charm, negotiate, and convince more effectively.' WHERE name = 'Silver Tongue';
UPDATE perks SET short_description = 'Agile and charming, but physically weaker.', long_description = 'Your slight build grants you unparalleled agility and an appealing presence, yet it limits your physical strength and stamina. Agility and Charisma increases by 2 and their max is now 12. However Strength and Endurance can''t be higher than 6.' WHERE name = 'Small Frame';
UPDATE perks SET short_description = 'Deal bonus holy damage.', long_description = 'Your attacks deal additional holy damage to corrupted or undead targets.' WHERE name = 'Smite the Unholy';
UPDATE perks SET short_description = 'Naturally persuasive, gaining a boost in conversations.', long_description = 'With an innate charm and eloquence, High Elves effortlessly navigate social landscapes, bending conversations to their will with ease and finesse. High Elves have a knack for getting what they want in conversations, gain a +2 Social Modifier.' WHERE name = 'Social Beings';
UPDATE perks SET short_description = 'Access connections.', long_description = 'Expand access to contacts and favors.' WHERE name = 'Social Network';
UPDATE perks SET short_description = 'Necrotic damage heals you instead of harming you.', long_description = 'Devoid of a soul, the forces of necrosis that would harm others instead rejuvenate you, turning death itself into a source of strength. You are immune to necrotic damage. In fact, you’re healed by it, you regain half of the necrotic damage inflicted upon you.' WHERE name = 'Soulless';
UPDATE perks SET short_description = 'Chance to repeat spells.', long_description = 'Spells occasionally replicate themselves at reduced power.' WHERE name = 'Spell Echo';
UPDATE perks SET short_description = 'Gain a spirit companion.', long_description = 'Form a bond with a guiding spirit that provides passive bonuses.' WHERE name = 'Spirit Bond';
UPDATE perks SET short_description = 'Absorb fallen spirits.', long_description = 'Collect echoes of fallen allies to regain energy or health.' WHERE name = 'Spirit Echo';
UPDATE perks SET short_description = 'Gain speed burst after dodge.', long_description = 'Performing evasive moves increases your running speed briefly.' WHERE name = 'Sprinter’s Focus';
UPDATE perks SET short_description = 'Summon lightning and thunder.', long_description = 'Call down storms to strike enemies with elemental fury.' WHERE name = 'Stormcaller';
UPDATE perks SET short_description = 'Spot enemy weaknesses.', long_description = 'Identify vulnerable enemies and expose them to allies.' WHERE name = 'Strategist’s Eye';
UPDATE perks SET short_description = 'Strong and enduring, but limited agility and charm.', long_description = 'Hardened by the trials of a ruthless environment, your physical prowess has been honed to perfection, though at the expense of social grace and nimbleness. Strength and Endurance increases by 2 and their max is now 12. However Agility and Charisma can''t be higher than 6.' WHERE name = 'Survival of the Fittest';
UPDATE perks SET short_description = 'Hardened against toxins and hazards.', long_description = 'Due to your upbringing in a hazardous land, you have learned to survive toxic and dangerous areas. When taking Hazard damage, you only take half.' WHERE name = 'Survivor';
UPDATE perks SET short_description = 'Avoid lethal nature damage.', long_description = 'Once per rest, survive a fatal natural hazard.' WHERE name = 'Survivor’s Luck';
UPDATE perks SET short_description = 'Gain defense while advancing.', long_description = 'Moving toward an enemy increases your defensive resistance temporarily.' WHERE name = 'Tactical Advance';
UPDATE perks SET short_description = 'Safer retreats.', long_description = 'Allies move faster and take less damage while disengaging.' WHERE name = 'Tactical Withdrawal';
UPDATE perks SET short_description = 'Slow time briefly.', long_description = 'Manipulate time’s flow to gain reaction advantage.' WHERE name = 'Temporal Distortion';
UPDATE perks SET short_description = 'Gain survival-oriented skills from the jungle.', long_description = 'You can choose one additional Tag skill among the following: Animal Handling, Survival or Medicine.' WHERE name = 'The Way of the Jungle';
UPDATE perks SET short_description = 'Create gadgets and traps.', long_description = 'Craft mechanical tools or temporary battlefield devices.' WHERE name = 'Tinker’s Touch';
UPDATE perks SET short_description = 'Wield heavy weapons easily.', long_description = 'Ignore penalties when using oversized or dual heavy weapons.' WHERE name = 'Titan Grip';
UPDATE perks SET short_description = 'Benefit from rare books.', long_description = 'Gaining tomes grants permanent knowledge bonuses.' WHERE name = 'Tome Collector';
UPDATE perks SET short_description = 'Place totems for buffs.', long_description = 'Totems radiate energy, strengthening allies nearby.' WHERE name = 'Totemic Strength';
UPDATE perks SET short_description = 'Identify tracks easily.', long_description = 'Recognize the species and direction of tracks.' WHERE name = 'Tracker';
UPDATE perks SET short_description = 'Guide others safely through the wild.', long_description = 'Your party ignores the first hour of travel penalties (fatigue, hunger, or navigation difficulty) each day.' WHERE name = 'Trailblazer';
UPDATE perks SET short_description = 'Improve mount performance.', long_description = 'Your mounts gain improved stamina and movement speed.' WHERE name = 'Trained Mounts';
UPDATE perks SET short_description = 'Dragons are your sworn enemy.', long_description = 'Reduce the Difficulty of Survival tests when tracking Dragons by 1. Re-roll 1d20 on every damaging attack against a Dragon. After killing a Dragon local villages will celebrate you as a hero, this means you sleep, drink and eat for free for the next 3 days.' WHERE name = 'Trained to Kill';
UPDATE perks SET short_description = 'Reveal hidden motives.', long_description = 'Discern deception and true emotions during interactions.' WHERE name = 'Truth Seeker';
UPDATE perks SET short_description = 'Ties to the criminal world give access to shady goods.', long_description = 'When in a settlement, you can always find illicit goods or services if they exist.' WHERE name = 'Underworld Connections';
UPDATE perks SET short_description = 'Hide after combat.', long_description = 'Enter stealth automatically after battle ends.' WHERE name = 'Unseen Exit';
UPDATE perks SET short_description = 'Reduce knockback.', long_description = 'Become harder to stagger or push back from hits.' WHERE name = 'Unyielding';
UPDATE perks SET short_description = 'Regenerate in natural terrain.', long_description = 'Heal faster while standing on soil, grass, or natural ground.' WHERE name = 'Verdant Renewal';
UPDATE perks SET short_description = 'Years of combat sharpen survival.', long_description = 'Gain +2 to Resistance tests when facing ambushes or sudden danger.' WHERE name = 'Veteran''s Instinct';
UPDATE perks SET short_description = 'Heal animals efficiently.', long_description = 'Treat wounded beasts more effectively, restoring greater health.' WHERE name = 'Veterinarian';
UPDATE perks SET short_description = 'Heal over time.', long_description = 'Your healing effects gradually restore health.' WHERE name = 'Vital Pulse';
UPDATE perks SET short_description = 'Move swiftly through terrain.', long_description = 'Travel faster and evade better when surrounded by nature.' WHERE name = 'Warden’s Step';
UPDATE perks SET short_description = 'Buff nearby allies.', long_description = 'Your shouts inspire allies, granting them small attack bonuses.' WHERE name = 'Warlord’s Command';
UPDATE perks SET short_description = 'Increase proficiency with chosen weapon type.', long_description = 'Gain improved control and critical chance with a selected weapon class.' WHERE name = 'Weapon Mastery';
UPDATE perks SET short_description = 'Resist harsh climates.', long_description = 'Gain protection against environmental effects.' WHERE name = 'Weathered';
UPDATE perks SET short_description = 'Enhanced detection.', long_description = 'Detect threats and prey earlier outdoors.' WHERE name = 'Wild Instinct';
UPDATE perks SET short_description = 'Your advice strengthens allies.', long_description = 'Once per session, grant an ally advantage (roll 1d20 twice, take the better) on a Lore or Insight test.' WHERE name = 'Wise Counsel';

UPDATE races SET short_description = 'Volcanic-born beings clad in obsidian.', long_description = 'Born of fire and forged in volcanic heartlands, Ashborne carry patches of living obsidian across their bodies. These hardened markings shield them from harm, embodying both their fiery origins and their resilience. Mysterious and formidable, they straddle the line between elemental power and mortal kin.' WHERE name = 'Ashborne';
UPDATE races SET short_description = 'Stout folk guided by ancient runes.', long_description = 'Every dwarf bears a rune that marks their destiny, weaving clan heritage with mystical power. Whether explorers driven by discovery, magisters deepened in arcane mastery, or artisans blessed with unmatched craft, dwarves live lives shaped by tradition and rune-bound fate. Hardy, loyal, and proud, they carry their culture as solidly as their stone-built halls.' WHERE name = 'Dwarf';
UPDATE races SET short_description = 'Towering survivors shaped by harsh lands.', long_description = 'Goliaths embody raw strength and endurance, honed by unforgiving environments that demand physical superiority. Their imposing presence and resilience make them formidable in battle, but this focus comes at a cost—their agility and social grace often lag behind. Survival defines their culture, and strength is their creed.' WHERE name = 'Goliath';
UPDATE races SET short_description = 'Nimble and charming, but physically small.', long_description = 'Halflings are quick-footed and warm-spirited, their small stature giving them an agility that belies their size. Loved for their charisma and adaptability, they thrive in both bustling towns and quiet villages. Yet their light build limits their strength and endurance, pushing them toward cleverness and community over brute force.' WHERE name = 'Halfling';
UPDATE races SET short_description = 'Charismatic masters of social influence.', long_description = 'High Elves wield charm and eloquence as deftly as any weapon. Their natural poise and sophistication grant them an edge in diplomacy, persuasion, and subtle manipulation. While sometimes seen as proud or aloof, they navigate social structures with unmatched finesse, often bending situations to their favor.' WHERE name = 'High Elves';
UPDATE races SET short_description = 'Adaptable and altruistic, humans excel at lifting others up.', long_description = 'Humans are known for their good-natured spirit and cooperative drive. Their generosity inspires trust and camaraderie, and their versatility allows them to thrive in nearly any role. While they may lack the extremes of other races, their strength lies in supporting allies and amplifying group success.' WHERE name = 'Human';
UPDATE races SET short_description = 'Soul-deprived beings sustained by death’s touch.', long_description = 'The Husk-Folk are eerie figures, hollowed of soul yet animated by a strange vitality. Where necrotic forces drain others, these beings draw strength, healing in the presence of decay. Neither fully dead nor alive, they stand apart from mortal kin, unsettling yet undeniably powerful in their bond to the energies of death.' WHERE name = 'Husk-Folk';
UPDATE races SET short_description = 'Hardy warriors with unyielding frames.', long_description = 'Orcs are defined by resilience, their bodies forged with dense bones and iron will. Injury that would break others often spurs them onward, granting them fearsome reputations as warriors and survivors. Their culture prizes toughness and determination, values reflected in their enduring presence on battlefield and frontier alike.' WHERE name = 'Orc';
UPDATE races SET short_description = 'Children of the forest bound to nature.', long_description = 'Wood Elves live in deep harmony with the natural world, their lives tied to the rhythm of the forest. Their herbivorous way of life strengthens their bond to the land, granting them resistance to disease and vitality from plant-based sustenance. Though gentle in outlook, their resilience comes from centuries of coexistence with wild and untamed realms.' WHERE name = 'Wood Elf';

UPDATE homelands SET short_description = 'Toxic, hazardous land where only hardened survivors thrive.', long_description = 'Due to your upbringing in a hazardous land, you have learned to survive toxic and dangerous areas. When taking Hazard damage, you only take half.' WHERE name = 'Aratori Dominion';
UPDATE homelands SET short_description = 'Deep, mystical woods where harmony with beasts is sacred.', long_description = 'When you encounter a creature with the Beast Keyword, it will never attack you on sight. Also gain 1 re-roll on all Animal Handling tests.' WHERE name = 'Asharati Forest';
UPDATE homelands SET short_description = 'Seafaring principality where piracy and trade intermingle.', long_description = 'Whenever you successfully salvage an area, you also gain a free roll on the Oddities and Valuables table.' WHERE name = 'Calatherian Principality';
UPDATE homelands SET short_description = 'Rootless wanderers who belong to no land or kingdom.', long_description = 'When you choose to not have a homeland, you choose to belong to a different entity. Thus you will instead gain a Perk from Background.' WHERE name = 'No Homeland';
UPDATE homelands SET short_description = 'Frozen lands where endurance against the cold is a way of life.', long_description = 'You can increase your survival rating by 1.5 when it comes to exposure to cold weather. Also, you can reduce Freeze Effects on you by 1.' WHERE name = 'The Frostheim Kingdom';
UPDATE homelands SET short_description = 'Scorching desert where resilience to heat is vital.', long_description = 'You can survive in hot weather without any penalty, and extreme hot weather is treated as hot weather.' WHERE name = 'The Obsidian Desert';
UPDATE homelands SET short_description = 'A refined kingdom where education and knowledge flourish.', long_description = 'You can choose one additional Tag skill among the following: Society, Warfare or Discipline. Also gain a language of your choice.' WHERE name = 'The Orotari Kingdom';
UPDATE homelands SET short_description = 'Harsh desert empire where heat and thirst shape daily survival.', long_description = 'You can increase your survival rating by 1.5 when it comes to exposure to hot weather. You can go an hour longer for every stage of Thirst and hot weather does not halve it.' WHERE name = 'The Quasarian Empire';
UPDATE homelands SET short_description = 'A patchwork of wild cities where adaptability is essential.', long_description = 'Due to the many different cities in the Untamed Highlands, you''ve learned to adapt to different societies. During carousing you can re-roll 1d20 on your Society test.' WHERE name = 'The Untamed Highlands';
UPDATE homelands SET short_description = 'Dense, perilous jungle where survival skills are second nature.', long_description = 'You can choose one additional Tag skill among the following: Animal Handling, Survival or Medicine.' WHERE name = 'The Ur''Holdum Jungle';
UPDATE homelands SET short_description = 'Harsh canyon homeland where only the strongest prevail.', long_description = 'Once per scene, you can completely ignore one attack that targets you.' WHERE name = 'Torgana Canyons';

UPDATE backgrounds SET short_description = 'Devout follower with religious training.', long_description = 'You are a kith of faith. An acolyte''s life is spent learning about modesty and a deeper understanding of your religion. Skills: Discipline, Arcana, Lore, Speech or Medicine. Equipment: Priest''s Garments.' WHERE name = 'Acolyte';
UPDATE backgrounds SET short_description = 'Craftsman devoted to honing a trade.', long_description = 'You are an artisan spending most of your life honing your craft. You might spend life becoming the best in one field or you might want to learn the basics of several. Skills: Society, Discipline, Sleight of Hand, Melee Weapons or Ranged Weapons. Equipment: Outfit of your choice and Crafting Tools of your choice.' WHERE name = 'Artisan';
UPDATE backgrounds SET short_description = 'Handler skilled at taming and caring for animals.', long_description = 'As a Beast Tamer you have had the responsibility of taming and keeping the animals of the tribe. Skills: Survival, Athletics, Acrobatics, Medicine or Insight.' WHERE name = 'Beast Tamer';
UPDATE backgrounds SET short_description = 'Streetwise rogue from a life outside the law.', long_description = 'You have led a criminal life learning to talk your way out of sticky situations, sneaking in the dark and living life among the less honored. Skills: Speech, Stealth, Investigation, Sleight of Hand or Insight. Equipment: Bandits Outfit and Lockpick Set. Language: Thieves'' Cant.' WHERE name = 'Criminal';
UPDATE backgrounds SET short_description = 'Elite warrior raised by the Dragon Knight Order.', long_description = 'As a Dragon Knight you were brought up at one of the holds of the Dragon Knight Order. This could be because one or both your parents are a part of the order, because you lost your parents to a dragon attack at a young age or something else. Skills: Melee Weapons, Ranged Weapons, Lore, Acrobatics, Parry, Warfare or Medicine. Equipment: A set of Leather Armor or Scale Armor.' WHERE name = 'Dragon Knight';
UPDATE backgrounds SET short_description = 'Wise figure recognized for knowledge and counsel.', long_description = 'As an Elder of the tribe you possess more knowledge than most and can offer wisdom to those who need it. Elder is merely a title and does not reflect age, one is named Elder when one shows an aptitude for learning and is proven to be wise. Skills: Medicine, Lore, Survival, Animal Handling, Insight or Speech.' WHERE name = 'Elder';
UPDATE backgrounds SET short_description = 'Performer who thrives in social settings.', long_description = 'You are an entertainer traveling around, meeting people and enjoying the social aspects of life. Skills: Speech, Society, Insight, Acrobatics, Parry or Linguistics. Equipment: Performer''s Outfit and an Instrument of Choice.' WHERE name = 'Entertainer';
UPDATE backgrounds SET short_description = 'Humble worker living off the land.', long_description = 'You are a simple farmer, such a life teaches one how to interact with animals, living off the land, crafting what you need and humble understanding of people. Skills: Animal Handling, Insight, Survival, Craft or Athletics. Equipment: A weapon of Rarity 0.' WHERE name = 'Farmer';
UPDATE backgrounds SET short_description = 'Arena warrior trained for brutal combat.', long_description = 'As a Gladiator you are familiar with combat and taking care of yourself. Skills: Warfare, Parry, Resistance or Athletics. Equipment: Tribal Outfit and a Weapon of Rarity 2 or lower.' WHERE name = 'Gladiator';
UPDATE backgrounds SET short_description = 'Solitary wanderer who chose a life apart.', long_description = 'As a Hermit you have cast aside the stressful life among society for the preferable life of solitude. Skills: Survival, Lore, Arcana, Medicine or Discipline.' WHERE name = 'Hermit';
UPDATE backgrounds SET short_description = 'Tracker and forager skilled in the wild.', long_description = 'As a Hunter you are adept at tracking animals or gathering fruits and berries. Skills: Animal Handling, Discipline, Ranged Weapons or Melee Weapons. Equipment: Ranger''s Outfit.' WHERE name = 'Hunter';
UPDATE backgrounds SET short_description = 'Seasoned fighter accustomed to hard travel.', long_description = 'As a Mercenary you are familiar with combat, traveling and taking care of yourself. Skills: Acrobatics, Melee Weapons, Ranged Weapons, Survival, Medicine, Parry or Resistance. Equipment: Wanderer''s Leather Clothing and a Weapon of Rarity 2 or lower.' WHERE name = 'Mercenary';
UPDATE backgrounds SET short_description = 'High-born individual with social standing.', long_description = 'You are part of a Nobel family or have spent a significant portion of your life becoming one. A Nobel life comes with great social standing, understanding of money and perhaps even leadership skills. Skills: Discipline, Society, Command, Linguistics or Lore. Equipment: Nobels Attire and 100 Gold.' WHERE name = 'Noble';
UPDATE backgrounds SET short_description = 'Guide skilled at navigating the wilds.', long_description = 'As a Pathfinder you have spent your life helping others navigate through landscapes without roads. Skills: Survival, Resistance, Athletics, Investigation or Stealth. Equipment: Ranger''s Outfit and a Map of your Homeland.' WHERE name = 'Pathfinder';
UPDATE backgrounds SET short_description = 'Seafarer hardened by life on the waves.', long_description = 'You have led a pirate''s life learning to talk your way out of sticky situations, sailing on the open sea and living life among the less honored. Skills: Speech, Stealth, Sleight of Hand, Insight or Navigation. Equipment: Pirate''s Attire.' WHERE name = 'Pirate';
UPDATE backgrounds SET short_description = 'Scholar steeped in knowledge and study.', long_description = 'You are a kith of books and study. You possess a vast amount of knowledge on several subjects or perhaps specialized in a few. Skills: Lore, Medicine, Arcana, Investigation or Navigation. Equipment: Scribe''s Robe.' WHERE name = 'Sage';
UPDATE backgrounds SET short_description = 'Disciplined fighter with military training.', long_description = 'You have served with the Military and gained adequate military training as well as a proper education. After your service you get to keep your gear as reward for your service. However you are expected to report in at your nearest military post should get the call for duty. Skills: Discipline, Command, Melee Weapons, Ranged Weapons, Lore or Warfare. Equipment: Full set of Chain Mail or Leather Armor.' WHERE name = 'Soldier';
UPDATE backgrounds SET short_description = 'Skilled infiltrator trained in intrigue.', long_description = 'Employed by the Nation or a business, you''ve led a life of infiltration and intrigue, learning how to sneak around, read people and fit in. Skills: Stealth, Speech, Insight, Investigation, Acrobatics or Society. Equipment: An Outfit of your choice.' WHERE name = 'Spy';
UPDATE backgrounds SET short_description = 'Wanderer of roads and markets, skilled at bargaining.', long_description = 'As a Trader you are familiar with the life on the road or sea as well as you are socially adept. You might have traveled across the border into neighboring nations. Skills: Speech, Survival, Navigation or Insight.' WHERE name = 'Trader';

UPDATE attacks SET short_description = 'An impact attack.', long_description = 'Driving the face of a shield or blunt weapon into the target.' WHERE name = 'Bash';
UPDATE attacks SET short_description = 'Increase a chosen defence.', long_description = 'You reinforce a target''s chosen defence until the end of the round.' WHERE name = 'Bolster';
UPDATE attacks SET short_description = 'A powerful chopping blow.', long_description = 'A downward chop with full force behind it.' WHERE name = 'Cleave';
UPDATE attacks SET short_description = 'A whip strike.', long_description = 'Snapping the whip at speed to cut or stun.' WHERE name = 'Crack';
UPDATE attacks SET short_description = 'A ranged attack.', long_description = 'Releasing a projectile at the target.' WHERE name = 'Fire';
UPDATE attacks SET short_description = 'Increase a target''s Deflection.', long_description = 'You protect a target by raising their Deflection until the end of the round.' WHERE name = 'Guard';
UPDATE attacks SET short_description = 'A tearing attack.', long_description = 'A vicious strike intended to tear and wound.' WHERE name = 'Rend';
UPDATE attacks SET short_description = 'A broad cutting attack.', long_description = 'A wide swinging cut aimed at exposed flesh.' WHERE name = 'Slash';
UPDATE attacks SET short_description = 'A crushing blow.', long_description = 'A heavy strike that crushes bone and armour.' WHERE name = 'Smash';
UPDATE attacks SET short_description = 'A basic attack.', long_description = 'A direct, unadorned blow.' WHERE name = 'Strike';
UPDATE attacks SET short_description = 'Swap to your other loadout.', long_description = 'You switch to your other prepared loadout.' WHERE name = 'Swap Loadout';
UPDATE attacks SET short_description = 'A wide sweeping attack.', long_description = 'A broad arc that can catch multiple foes.' WHERE name = 'Sweep';
UPDATE attacks SET short_description = 'A precise piercing attack.', long_description = 'A focused lunge driving the point into the target.' WHERE name = 'Thrust';
UPDATE attacks SET short_description = 'Delay your next action.', long_description = 'You hold back and act later, improving your timing on the next action.' WHERE name = 'Wait';

UPDATE npcs SET short_description = 'A desperate highway thief.', long_description = 'A rough criminal who relies on aggression, speed, and opportunistic attacks.' WHERE name = 'Bandit Raider';
UPDATE npcs SET short_description = 'A dangerous occult practitioner.', long_description = 'A sinister humanoid who combines ritual knowledge, fanatic resolve, and unsettling magical talent.' WHERE name = 'Cult Adept';
UPDATE npcs SET short_description = 'A thick-skinned charging beast.', long_description = 'A vicious boar that relies on momentum, toughness, and savage impact to overwhelm prey.' WHERE name = 'Dire Boar';
UPDATE npcs SET short_description = 'A feral flesh-hungry undead.', long_description = 'A swift and ravenous undead horror that attacks in frenzied bursts and drags foes down.' WHERE name = 'Ghoul';
UPDATE npcs SET short_description = 'A reanimated undead warrior.', long_description = 'A brittle but relentless undead creature animated by necrotic force.' WHERE name = 'Skeleton';
UPDATE npcs SET short_description = 'A trained town defender.', long_description = 'A local guard equipped for basic melee combat and watch duty.' WHERE name = 'Village Guard';
UPDATE npcs SET short_description = 'A fast hunting beast.', long_description = 'A lean predator that fights with quick movement, sharp instincts, and relentless bites.' WHERE name = 'Wolf';
UPDATE npcs SET short_description = 'A shambling corpse driven onward.', long_description = 'A decaying undead creature that endures punishment and closes in through sheer persistence.' WHERE name = 'Zombie';

UPDATE resources SET short_description = 'Faster research.', long_description = 'Complete study or lore research more efficiently.' WHERE name = 'Academic Diligence';
UPDATE resources SET short_description = 'Devout follower with religious training.', long_description = 'You are a kith of faith. An acolyte''s life is spent learning about modesty and a deeper understanding of your religion. Skills: Discipline, Arcana, Lore, Speech or Medicine. Equipment: Priest''s Garments.' WHERE name = 'Acolyte';
UPDATE resources SET short_description = 'Flexible social skills from varied cultures.', long_description = 'Due to the many different cities in the Untamed Highlands, you''ve learned to adapt to different societies. During carousing you can re-roll 1d20 on your Society test.' WHERE name = 'Adaptable';
UPDATE resources SET short_description = 'Intimidate lesser beasts.', long_description = 'Your commanding aura deters smaller or weaker animals from attacking.' WHERE name = 'Alpha Presence';
UPDATE resources SET short_description = 'Damage bonus from stealth.', long_description = 'Deal extra damage on attacks from hiding.' WHERE name = 'Ambusher';
UPDATE resources SET short_description = 'Solve puzzles faster.', long_description = 'Speed up deduction-based tasks and research.' WHERE name = 'Analyst';
UPDATE resources SET short_description = 'Exploit anatomy.', long_description = 'Deal extra damage to organic foes through precision.' WHERE name = 'Anatomist';
UPDATE resources SET short_description = 'Summon ancestral protection.', long_description = 'Call upon ancient spirits to shield allies from harm.' WHERE name = 'Ancestral Guardian';
