UPDATE resources SET short_description = 'Hardy warriors with unyielding frames.', long_description = 'Orcs are defined by resilience, their bodies forged with dense bones and iron will. Injury that would break others often spurs them onward, granting them fearsome reputations as warriors and survivors. Their culture prizes toughness and determination, values reflected in their enduring presence on battlefield and frontier alike.' WHERE name = 'Orc';
