UPDATE resources SET short_description = 'Sturdy bones give you an edge against injuries.', long_description = 'Your bones are exceptionally sturdy, providing a robust defense against injuries that would cripple others. When making a Fortitude test to resist injury, gain +5 for that test.' WHERE name = 'Resilient Frame';
UPDATE resources SET short_description = 'Represents mental fortitude and determination.', long_description = 'Resolve reflects a character’s strength of will, focus, and emotional stability under pressure. It determines how well a character maintains concentration during combat and how resistant they are to negative mental or magical effects. Characters with high Resolve can shrug off debilitating conditions and remain steadfast in challenging situations.' WHERE name = 'Resolve';
