UPDATE damage_origins SET short_description = 'The measure of strength, speed, and stamina in motion.', long_description = 'Athletics is the discipline of the body pushed to its limits — running, climbing, leaping, and enduring trials that test both muscle and breath. It is the difference between faltering on the field and pressing forward with unyielding vigor.' WHERE name = 'Athletics';
