UPDATE damage_origins SET short_description = 'Identify tracks easily.', long_description = 'Recognize the species and direction of tracks.' WHERE name = 'Tracker';
UPDATE damage_origins SET short_description = 'Wanderer of roads and markets, skilled at bargaining.', long_description = 'As a Trader you are familiar with the life on the road or sea as well as you are socially adept. You might have traveled across the border into neighboring nations. Skills: Speech, Survival, Navigation or Insight.' WHERE name = 'Trader';
