UPDATE damage_origins SET short_description = 'Improve mount performance.', long_description = 'Your mounts gain improved stamina and movement speed.' WHERE name = 'Trained Mounts';
UPDATE damage_origins SET short_description = 'Dragons are your sworn enemy.', long_description = 'Reduce the Difficulty of Survival tests when tracking Dragons by 1. Re-roll 1d20 on every damaging attack against a Dragon. After killing a Dragon local villages will celebrate you as a hero, this means you sleep, drink and eat for free for the next 3 days.' WHERE name = 'Trained to Kill';
