UPDATE damage_origins SET short_description = 'Increase proficiency with chosen weapon type.', long_description = 'Gain improved control and critical chance with a selected weapon class.' WHERE name = 'Weapon Mastery';
UPDATE damage_origins SET short_description = 'Resist harsh climates.', long_description = 'Gain protection against environmental effects.' WHERE name = 'Weathered';
UPDATE damage_origins SET short_description = 'Enhanced detection.', long_description = 'Detect threats and prey earlier outdoors.' WHERE name = 'Wild Instinct';
UPDATE damage_origins SET short_description = 'Your advice strengthens allies.', long_description = 'Once per session, grant an ally advantage (roll 1d20 twice, take the better) on a Lore or Insight test.' WHERE name = 'Wise Counsel';
UPDATE damage_origins SET short_description = 'Children of the forest bound to nature.', long_description = 'Wood Elves live in deep harmony with the natural world, their lives tied to the rhythm of the forest. Their herbivorous way of life strengthens their bond to the land, granting them resistance to disease and vitality from plant-based sustenance. Though gentle in outlook, their resilience comes from centuries of coexistence with wild and untamed realms.' WHERE name = 'Wood Elf';

