UPDATE damage_types SET short_description = 'Flexible social skills from varied cultures.', long_description = 'Due to the many different cities in the Untamed Highlands, you''ve learned to adapt to different societies. During carousing you can re-roll 1d20 on your Society test.' WHERE name = 'Adaptable';
