UPDATE damage_types SET short_description = 'The bond between mortal and beast.', long_description = 'Animal handling is the art of trust and instinct, guiding creatures through patience rather than force. It is the steady hand that calms a frightened steed, the subtle command that turns a hound against its quarry, and the quiet respect that earns loyalty from claw and fang alike.' WHERE name = 'Animal Handling';
