UPDATE damage_types SET short_description = 'The memory of stories, histories, and knowledge.', long_description = 'Lore is the collection of all that has been learned and passed down: myths and histories, secrets of the land, and wisdom preserved through generations. Those versed in lore hold the keys to understanding both the past and the present.' WHERE name = 'Lore';
UPDATE damage_types SET short_description = 'Share wisdom.', long_description = 'Allies gain bonus experience through your teaching.' WHERE name = 'Lorekeeper’s Guidance';
