UPDATE damage_types SET short_description = 'Reduce mana costs.', long_description = 'All spells cost slightly less to cast, conserving magical resources.' WHERE name = 'Mana Efficiency';
UPDATE damage_types SET short_description = 'Alter relationships.', long_description = 'Subtly sway NPC relationships through dialogue.' WHERE name = 'Manipulator';
UPDATE damage_types SET short_description = 'Recover stamina faster.', long_description = 'Regain endurance at an accelerated rate during rest or motion.' WHERE name = 'Marathoner';
UPDATE damage_types SET short_description = 'Patience rewards your aim.', long_description = 'If you spend one turn aiming, your next Ranged attack deals +2 damage.' WHERE name = 'Marksman''s Patience';
UPDATE damage_types SET short_description = 'Sacrifice health for allies.', long_description = 'Trade your vitality to empower allies’ attacks.' WHERE name = 'Martyr’s Will';
