UPDATE effects SET short_description = 'Sense emotions.', long_description = 'Understand emotional states to defuse tense situations.' WHERE name = 'Empathic Reading';
UPDATE effects SET short_description = 'Reduce stamina drain.', long_description = 'Run, climb, or swim for longer periods before tiring.' WHERE name = 'Enduring Stride';
UPDATE effects SET short_description = 'Performer who thrives in social settings.', long_description = 'You are an entertainer traveling around, meeting people and enjoying the social aspects of life. Skills: Speech, Society, Insight, Acrobatics, Parry or Linguistics. Equipment: Performer''s Outfit and an Instrument of Choice.' WHERE name = 'Entertainer';
