UPDATE ranges SET short_description = 'Avoid some combat.', long_description = 'Talk your way out of minor hostile encounters.' WHERE name = 'Fast Talker';
UPDATE ranges SET short_description = 'Ignore fear penalties.', long_description = 'Speak confidently even under duress.' WHERE name = 'Fearless Orator';
UPDATE ranges SET short_description = 'Gain mana when resisted.', long_description = 'Regain energy when an enemy resists or avoids your magic.' WHERE name = 'Feedback Loop';
