UPDATE spells SET short_description = 'Repair gear in the field.', long_description = 'Fix broken weapons or armor outside of a forge.' WHERE name = 'Field Repairs';
UPDATE spells SET short_description = 'Campfire buff bonuses.', long_description = 'Resting near fire grants temporary combat buffs.' WHERE name = 'Firekeeper';
