UPDATE spells SET short_description = 'The memory of stories, histories, and knowledge.', long_description = 'Lore is the collection of all that has been learned and passed down: myths and histories, secrets of the land, and wisdom preserved through generations. Those versed in lore hold the keys to understanding both the past and the present.' WHERE name = 'Lore';
UPDATE spells SET short_description = 'Share wisdom.', long_description = 'Allies gain bonus experience through your teaching.' WHERE name = 'Lorekeeper’s Guidance';
UPDATE spells SET short_description = 'Auto-loot valuables.', long_description = 'Automatically collect nearby small valuables.' WHERE name = 'Magpie Instinct';
UPDATE spells SET short_description = 'Reduce mana costs.', long_description = 'All spells cost slightly less to cast, conserving magical resources.' WHERE name = 'Mana Efficiency';
UPDATE spells SET short_description = 'Alter relationships.', long_description = 'Subtly sway NPC relationships through dialogue.' WHERE name = 'Manipulator';
UPDATE spells SET short_description = 'Recover stamina faster.', long_description = 'Regain endurance at an accelerated rate during rest or motion.' WHERE name = 'Marathoner';
UPDATE spells SET short_description = 'Patience rewards your aim.', long_description = 'If you spend one turn aiming, your next Ranged attack deals +2 damage.' WHERE name = 'Marksman''s Patience';
UPDATE spells SET short_description = 'Sacrifice health for allies.', long_description = 'Trade your vitality to empower allies’ attacks.' WHERE name = 'Martyr’s Will';
UPDATE spells SET short_description = 'Craft higher-quality gear.', long_description = 'Items you make start with superior base stats.' WHERE name = 'Master Artisan';
UPDATE spells SET short_description = 'Expert at hiding your true identity.', long_description = 'Gain +2 to Stealth or Society tests when attempting to conceal your identity.' WHERE name = 'Master of Disguise';
UPDATE spells SET short_description = 'Your creations carry exceptional quality.', long_description = 'Once per session, you may treat a crafted item as if its rarity were 1 higher when using it in a skill test.' WHERE name = 'Masterwork';
UPDATE spells SET short_description = 'Resolve disputes peacefully.', long_description = 'Calm heated arguments and prevent violence.' WHERE name = 'Mediator';
UPDATE spells SET short_description = 'The art of healing and preserving life.', long_description = 'Medicine is the knowledge of flesh and spirit, of how wounds may be closed and ailments eased. It is the healer’s craft, restoring strength where it has faltered and warding off the grasp of death itself.' WHERE name = 'Medicine';
UPDATE spells SET short_description = 'Regain mana while idle.', long_description = 'Resting briefly restores magical or focus energy.' WHERE name = 'Meditative Focus';
UPDATE spells SET short_description = 'Seasoned fighter accustomed to hard travel.', long_description = 'As a Mercenary you are familiar with combat, traveling and taking care of yourself. Skills: Acrobatics, Melee Weapons, Ranged Weapons, Survival, Medicine, Parry or Resistance. Equipment: Wanderer''s Leather Clothing and a Weapon of Rarity 2 or lower.' WHERE name = 'Mercenary';
