UPDATE spells SET short_description = 'Place totems for buffs.', long_description = 'Totems radiate energy, strengthening allies nearby.' WHERE name = 'Totemic Strength';
UPDATE spells SET short_description = 'Identify tracks easily.', long_description = 'Recognize the species and direction of tracks.' WHERE name = 'Tracker';
UPDATE spells SET short_description = 'Wanderer of roads and markets, skilled at bargaining.', long_description = 'As a Trader you are familiar with the life on the road or sea as well as you are socially adept. You might have traveled across the border into neighboring nations. Skills: Speech, Survival, Navigation or Insight.' WHERE name = 'Trader';
UPDATE spells SET short_description = 'Guide others safely through the wild.', long_description = 'Your party ignores the first hour of travel penalties (fatigue, hunger, or navigation difficulty) each day.' WHERE name = 'Trailblazer';
