UPDATE spells SET short_description = 'Dragons are your sworn enemy.', long_description = 'Reduce the Difficulty of Survival tests when tracking Dragons by 1. Re-roll 1d20 on every damaging attack against a Dragon. After killing a Dragon local villages will celebrate you as a hero, this means you sleep, drink and eat for free for the next 3 days.' WHERE name = 'Trained to Kill';
UPDATE spells SET short_description = 'Reveal hidden motives.', long_description = 'Discern deception and true emotions during interactions.' WHERE name = 'Truth Seeker';
UPDATE spells SET short_description = 'Ties to the criminal world give access to shady goods.', long_description = 'When in a settlement, you can always find illicit goods or services if they exist.' WHERE name = 'Underworld Connections';
