UPDATE armor SET short_description = 'Toxic, hazardous land where only hardened survivors thrive.', long_description = 'Due to your upbringing in a hazardous land, you have learned to survive toxic and dangerous areas. When taking Hazard damage, you only take half.' WHERE name = 'Aratori Dominion';
