UPDATE armor SET short_description = 'Handler skilled at taming and caring for animals.', long_description = 'As a Beast Tamer you have had the responsibility of taming and keeping the animals of the tribe. Skills: Survival, Athletics, Acrobatics, Medicine or Insight.' WHERE name = 'Beast Tamer';
UPDATE armor SET short_description = 'Craft animal snares.', long_description = 'Create traps to capture or damage wild beasts.' WHERE name = 'Beast Trap';
UPDATE armor SET short_description = 'Tame animals mid-battle.', long_description = 'Attempt to pacify or charm wild creatures during combat.' WHERE name = 'Beast Whisper';
UPDATE armor SET short_description = 'Charm animals temporarily.', long_description = 'Turn beasts into allies by speaking their primal language.' WHERE name = 'Beast Whisperer';
