UPDATE armor SET short_description = 'Dodges restore stamina.', long_description = 'Perfect evasions regenerate a small portion of stamina.' WHERE name = 'Defensive Footwork';
UPDATE armor SET short_description = 'Adapted to endure scorching desert climates.', long_description = 'You can increase your survival rating by 1.5 when it comes to exposure to hot weather. You can go an hour longer for every stage of Thirst and hot weather does not halve it.' WHERE name = 'Desert Adventurer';
UPDATE armor SET short_description = 'Expose deception.', long_description = 'Notice verbal and physical cues of lying characters.' WHERE name = 'Detect Lies';
UPDATE armor SET short_description = 'Represents speed, coordination, and reflexes.', long_description = 'Dexterity reflects a character’s agility and precision in both physical and mental actions. It governs how quickly and efficiently a character can move, attack, and react. High Dexterity grants additional action points, allowing more actions per turn, and improves deflection, helping to avoid incoming attacks.' WHERE name = 'Dexterity';
UPDATE armor SET short_description = 'Win favor among nobles.', long_description = 'Speak with authority to gain favor in upper circles.' WHERE name = 'Diplomat';
