UPDATE armor SET short_description = 'Summon a protective barrier.', long_description = 'Manifest divine light that absorbs incoming damage.' WHERE name = 'Divine Shield';
UPDATE armor SET short_description = 'Elite warrior raised by the Dragon Knight Order.', long_description = 'As a Dragon Knight you were brought up at one of the holds of the Dragon Knight Order. This could be because one or both your parents are a part of the order, because you lost your parents to a dragon attack at a young age or something else. Skills: Melee Weapons, Ranged Weapons, Lore, Acrobatics, Parry, Warfare or Medicine. Equipment: A set of Leather Armor or Scale Armor.' WHERE name = 'Dragon Knight';
UPDATE armor SET short_description = 'Stout folk guided by ancient runes.', long_description = 'Every dwarf bears a rune that marks their destiny, weaving clan heritage with mystical power. Whether explorers driven by discovery, magisters deepened in arcane mastery, or artisans blessed with unmatched craft, dwarves live lives shaped by tradition and rune-bound fate. Hardy, loyal, and proud, they carry their culture as solidly as their stone-built halls.' WHERE name = 'Dwarf';
UPDATE armor SET short_description = 'Spot hidden details.', long_description = 'Identify clues, tracks, or secrets others miss.' WHERE name = 'Eagle Eye';
UPDATE armor SET short_description = 'Harden your skin like stone.', long_description = 'Enhance physical resistance by drawing on the power of the earth.' WHERE name = 'Earthen Armor';
