UPDATE armor SET short_description = 'Lower command cost.', long_description = 'Reduce focus or resource cost of issuing tactical commands.' WHERE name = 'Efficient Command';
UPDATE armor SET short_description = 'Reduce crafting costs.', long_description = 'Use fewer materials and waste less when crafting.' WHERE name = 'Efficient Smith';
UPDATE armor SET short_description = 'Wise figure recognized for knowledge and counsel.', long_description = 'As an Elder of the tribe you possess more knowledge than most and can offer wisdom to those who need it. Elder is merely a title and does not reflect age, one is named Elder when one shows an aptitude for learning and is proven to be wise. Skills: Medicine, Lore, Survival, Animal Handling, Insight or Speech.' WHERE name = 'Elder';
UPDATE armor SET short_description = 'Reduce ancient spell cost.', long_description = 'Casting ancient or forgotten magic consumes less energy.' WHERE name = 'Elder Scholar';
